import React, { useState, useEffect } from 'react';
import { ToastContainer, toast } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';

function AdminDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [users, setUsers] = useState([]);
  const [bookings, setBookings] = useState([]);
  const [services, setServices] = useState([]);
  const [stats, setStats] = useState({
    users: { total: 0, customers: 0, providers: 0, drivers: 0 },
    services: { total: 0 },
    bookings: { total: 0, completed: 0, pending: 0, cancelled: 0 },
    revenue: { total: 0, platformCommission: 0, providerPayouts: 0, monthlyGrowth: 0 },
    platform: { rating: 0, totalReviews: 0, responseTime: 2.5, retentionRate: 78 }
  });
  const [loading, setLoading] = useState(true);
  const [filterRole, setFilterRole] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [showNotifications, setShowNotifications] = useState(false);
  const [unreadCount, setUnreadCount] = useState(5);

  const token = localStorage.getItem('token');

  useEffect(() => {
    fetchAllData();
  }, []);

  const fetchAllData = async () => {
    setLoading(true);
    try {
      const statsRes = await fetch('http://localhost:5000/api/admin/stats', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const statsData = await statsRes.json();
      if (statsData.success) {
        console.log('Stats from backend:', statsData.stats);
        setStats(statsData.stats);
      }

      const usersRes = await fetch('http://localhost:5000/api/admin/users', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const usersData = await usersRes.json();
      if (usersData.success) setUsers(usersData.users);

      const bookingsRes = await fetch('http://localhost:5000/api/admin/bookings', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const bookingsData = await bookingsRes.json();
      if (bookingsData.success) setBookings(bookingsData.bookings);

      const servicesRes = await fetch('http://localhost:5000/api/admin/services', {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      const servicesData = await servicesRes.json();
      if (servicesData.success) setServices(servicesData.services);
    } catch (error) {
      console.error('Error fetching data:', error);
      toast.error('Failed to load data');
    } finally {
      setLoading(false);
    }
  };

  const updateUserStatus = async (userId, isActive) => {
    try {
      const res = await fetch(`http://localhost:5000/api/admin/users/${userId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify({ isActive })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`User ${isActive ? 'activated' : 'suspended'}`);
        fetchAllData();
      }
    } catch (error) {
      toast.error('Failed to update user');
    }
  };

  const verifyUser = async (userId, isVerified, role) => {
    try {
      const res = await fetch(`http://localhost:5000/api/admin/users/${userId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify({ isVerified })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`${role} ${isVerified ? 'verified' : 'unverified'}`);
        fetchAllData();
      }
    } catch (error) {
      toast.error('Failed to verify user');
    }
  };

  const deleteUser = async (userId, userName) => {
    if (window.confirm(`Are you sure you want to permanently delete ${userName}?`)) {
      try {
        const res = await fetch(`http://localhost:5000/api/admin/users/${userId}`, {
          method: 'DELETE',
          headers: { 'Authorization': `Bearer ${token}` }
        });
        const data = await res.json();
        if (data.success) {
          toast.success(`${userName} deleted successfully`);
          fetchAllData();
        }
      } catch (error) {
        toast.error('Failed to delete user');
      }
    }
  };

  const changeUserRole = async (userId, newRole) => {
    try {
      const res = await fetch(`http://localhost:5000/api/admin/users/${userId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify({ role: newRole })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`User role changed to ${newRole}`);
        fetchAllData();
      }
    } catch (error) {
      toast.error('Failed to change role');
    }
  };

  const toggleServiceStatus = async (serviceId, isActive) => {
    try {
      const res = await fetch(`http://localhost:5000/api/admin/services/${serviceId}/status`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${token}` },
        body: JSON.stringify({ isActive: !isActive })
      });
      const data = await res.json();
      if (data.success) {
        toast.success(`Service ${!isActive ? 'activated' : 'hidden'}`);
        fetchAllData();
      }
    } catch (error) {
      toast.error('Failed to update service');
    }
  };

  const getRoleBadge = (role) => {
    const config = {
      customer: { bg: '#d1fae5', color: '#065f46', icon: '👤' },
      provider: { bg: '#e0e7ff', color: '#4338ca', icon: '🔧' },
      driver: { bg: '#fef3c7', color: '#92400e', icon: '🚗' },
      admin: { bg: '#f3e8ff', color: '#7c3aed', icon: '👑' }
    };
    const c = config[role] || { bg: '#f3f4f6', color: '#6b7280', icon: '❓' };
    return React.createElement('span', {
      style: { backgroundColor: c.bg, color: c.color, padding: '4px 10px', borderRadius: '20px', fontSize: '12px', display: 'inline-flex', alignItems: 'center', gap: '5px' }
    }, c.icon, ' ', role);
  };

  const getStatusBadge = (status) => {
    const colors = { pending: '#f59e0b', confirmed: '#10b981', completed: '#8b5cf6', cancelled: '#ef4444' };
    return React.createElement('span', {
      style: { backgroundColor: colors[status] || '#6b7280', color: 'white', padding: '4px 10px', borderRadius: '20px', fontSize: '11px', display: 'inline-block' }
    }, status);
  };

  const filteredUsers = users.filter(user => {
    const matchesRole = filterRole === 'all' || user.role === filterRole;
    const matchesSearch = searchTerm === '' || 
      user.email?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.firstName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.lastName?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      user.businessName?.toLowerCase().includes(searchTerm.toLowerCase());
    return matchesRole && matchesSearch;
  });

  const weeklyData = [
    { day: 'Mon', bookings: bookings.filter(b => new Date(b.createdAt).getDay() === 1).length },
    { day: 'Tue', bookings: bookings.filter(b => new Date(b.createdAt).getDay() === 2).length },
    { day: 'Wed', bookings: bookings.filter(b => new Date(b.createdAt).getDay() === 3).length },
    { day: 'Thu', bookings: bookings.filter(b => new Date(b.createdAt).getDay() === 4).length },
    { day: 'Fri', bookings: bookings.filter(b => new Date(b.createdAt).getDay() === 5).length },
    { day: 'Sat', bookings: bookings.filter(b => new Date(b.createdAt).getDay() === 6).length },
    { day: 'Sun', bookings: bookings.filter(b => new Date(b.createdAt).getDay() === 0).length }
  ];

  const maxBookings = Math.max(...weeklyData.map(d => d.bookings), 1);

  return React.createElement('div', { style: styles.dashboard },
    React.createElement(ToastContainer, { position: 'top-right' }),

    // Header
    React.createElement('div', { style: styles.header },
      React.createElement('div', { style: styles.logoSection },
        React.createElement('span', { style: styles.logoIcon }, '👑'),
        React.createElement('div', null,
          React.createElement('h1', { style: styles.logoText }, 'Car Care Connect - Admin'),
          React.createElement('div', { style: styles.headerSubtitle }, 'Platform Management Dashboard')
        )
      ),
      React.createElement('div', { style: styles.headerRight },
        React.createElement('div', { style: styles.notificationIcon, onClick: () => setShowNotifications(!showNotifications) }, '🔔', unreadCount > 0 && React.createElement('span', { style: styles.notificationBadge }, unreadCount)),
        React.createElement('div', { style: styles.userInfo },
          React.createElement('img', { src: `https://ui-avatars.com/api/?background=8b5cf6&color=fff&name=${user?.firstName}`, alt: 'avatar', style: styles.avatar }),
          React.createElement('div', null,
            React.createElement('div', { style: styles.userName }, user?.firstName, ' ', user?.lastName),
            React.createElement('div', { style: styles.userEmail }, 'Super Admin')
          ),
          React.createElement('button', { onClick: onLogout, style: styles.logoutButton }, '🚪')
        )
      )
    ),

    // Stats Cards
    React.createElement('div', { style: styles.statsGrid },
      React.createElement('div', { style: styles.statCard },
        React.createElement('div', { style: styles.statIcon }, '👥'),
        React.createElement('div', { style: styles.statInfo },
          React.createElement('h3', null, 'Total Users'),
